// ui/routes/shell/app-update.mjs — feature "shell". Generated by tools/split-by-feature.mjs v1;
// the body of register() was moved verbatim from ui/server.mjs. Edit it here from now on.
import { updateCheckEnabled } from '../../../src/core/settings.mjs';
import { readUpdateRecord, startCommand, writeUpdateRecord } from '../../../src/core/ui-update.mjs';
import { AUTO_RESTART_MIN, annotateVersions, canAutoRestart, canonicalVersion, compareVersions, parseVersion } from '../../../src/core/update-check.mjs';
import fs from 'node:fs';
import fsp from 'node:fs/promises';
import path from 'node:path';
import { AGENTS_DIR, PKG_VERSION, PROJECT_ROOT, RUNNING_VERSION, SKILLS_DIR, agentMayBeCaller, badRequest, currentUpdateEligibility, lastUpdateResult, requireFsAllowed, resolveProjectDir, terminalSameOrigin, updateChecker, updatePort, updatePreview, versionLister, versionPayload } from '../../server.mjs';

export function register(app) {

// ---------------------------------------------------------------------------
// POST /api/install  -> copy agents + skill into <projectDir>/.claude
// body: { projectDir }
// ---------------------------------------------------------------------------
app.post('/api/install', async (req, res) => {
  const projectDir = resolveProjectDir((req.body || {}).projectDir);
  if (!projectDir) return badRequest(res, 'projectDir is required');
  if (!(await requireFsAllowed(req, res, [projectDir]))) return;
  try {
    const result = await installAgents(projectDir);
    res.json(result);
  } catch (err) {
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

// GET  /api/app/version       → { current, latest, status, checkedAt, enabled, links } (issue #841);
//                                status 'source' on a git checkout (no npm request, no update links).
// POST /api/app/version/check → the same, re-checking npm unless the last try is under a minute old.
// Read-only: nothing here installs or restarts anything. Failures read as status 'unknown'.
app.get('/api/app/version', async (req, res) => {
  res.set('Cache-Control', 'no-store').json(versionPayload(await updateChecker.status()));
});
app.post('/api/app/version/check', async (req, res) => {
  res.set('Cache-Control', 'no-store').json(versionPayload(await updateChecker.status({ force: true })));
});

// Manual update (issue #841). GET reads only; POST asks the `worca ui` supervisor to install: it
// writes <worcaHome>/update.json, drains like a stop, and exits UPDATE_EXIT_CODE. Nothing installs here.
app.get('/api/app/update', async (req, res) => {
  const elig = await currentUpdateEligibility(req);
  const list = updateCheckEnabled() ? await versionLister.get() : versionLister.peek();
  const rc = list?.distTags?.rc || null;
  res.set('Cache-Control', 'no-store').json({
    ...elig, current: RUNNING_VERSION, distTags: list?.distTags || null,
    rcNewer: !!(rc && parseVersion(PKG_VERSION) && compareVersions(parseVersion(rc), parseVersion(PKG_VERSION)) > 0),
    autoRestartMin: AUTO_RESTART_MIN, startCommand: startCommand(updatePort()), lastResult: lastUpdateResult(),
  });
});
app.get('/api/app/update/versions', async (req, res) => {
  const list = await versionLister.get({ force: req.query.refresh === '1' });
  if (!list) return res.status(502).json({ error: 'Could not load the version list from npm. Try again in a moment.', code: 'VERSIONS_UNAVAILABLE' });
  res.set('Cache-Control', 'no-store').json({ current: RUNNING_VERSION, distTags: list.distTags, versions: annotateVersions(list, PKG_VERSION) });
});
app.get('/api/app/update/preview', async (req, res) => {
  // Lists run titles: answer only this Worca's own pages, never an agent.
  if (!terminalSameOrigin(req) || agentMayBeCaller(req)) return res.status(403).json({ error: 'Updates only answer pages served by this Worca.', code: 'UPDATE_CROSS_ORIGIN' });
  const target = canonicalVersion(req.query.version);
  if (!target) return res.status(400).json({ error: 'Pick a version from the list.', code: 'UPDATE_BAD_VERSION' });
  res.set('Cache-Control', 'no-store').json({ target, autoRestart: canAutoRestart(target), startCommand: startCommand(updatePort()), ...updatePreview() });
});
app.post('/api/app/update/dismiss', (req, res) => {
  if (!terminalSameOrigin(req) || agentMayBeCaller(req)) return res.status(403).json({ error: 'Not from here.', code: 'UPDATE_CROSS_ORIGIN' });
  const rec = readUpdateRecord();
  if (rec && (rec.state === 'failed' || rec.state === 'installed')) writeUpdateRecord({ ...rec, state: 'dismissed' });
  res.json({ ok: true });
});

// ---------------------------------------------------------------------------
// Install logic (mirrors tools/install.mjs): copy agents/*.md and
// skills/worca/** into <projectDir>/.claude/...
// ---------------------------------------------------------------------------
async function installAgents(projectDir) {
  const claudeDir = path.join(projectDir, '.claude');
  const agentsTarget = path.join(claudeDir, 'agents');
  const skillTarget = path.join(claudeDir, 'skills', 'worca');
  await fsp.mkdir(agentsTarget, { recursive: true });
  await fsp.mkdir(skillTarget, { recursive: true });

  const copied = [];

  // Copy agents/*.md
  if (fs.existsSync(AGENTS_DIR)) {
    const entries = await fsp.readdir(AGENTS_DIR);
    for (const name of entries) {
      if (!name.endsWith('.md')) continue;
      const from = path.join(AGENTS_DIR, name);
      const to = path.join(agentsTarget, name);
      await fsp.copyFile(from, to);
      copied.push(path.relative(projectDir, to));
    }
  }

  // Copy skills/worca/** recursively
  const skillSrc = path.join(SKILLS_DIR, 'worca');
  if (fs.existsSync(skillSrc)) {
    await copyDir(skillSrc, skillTarget, projectDir, copied);
    // Personalize the copied SKILL.md so /worca targets this repo's path.
    await rewriteSkillRepoPath(skillTarget, PROJECT_ROOT);
  }

  return {
    ok: true,
    target: claudeDir,
    copied,
    hint: 'Open Claude Code in this folder and run: /worca <prompt>',
  };
}

/**
 * Rewrite the `<WORCA_REPO>` placeholder in an installed SKILL.md to this repo's
 * absolute path. Best-effort; never throws.
 */
async function rewriteSkillRepoPath(skillTarget, repoRoot) {
  const skillMd = path.join(skillTarget, 'SKILL.md');
  try {
    const original = await fsp.readFile(skillMd, 'utf8');
    const rewritten = original.split('<WORCA_REPO>').join(repoRoot);
    if (rewritten !== original) await fsp.writeFile(skillMd, rewritten, 'utf8');
  } catch {
    /* no SKILL.md or unreadable — skip */
  }
}

async function copyDir(srcDir, destDir, baseForRel, copiedOut) {
  await fsp.mkdir(destDir, { recursive: true });
  const entries = await fsp.readdir(srcDir, { withFileTypes: true });
  for (const ent of entries) {
    const from = path.join(srcDir, ent.name);
    const to = path.join(destDir, ent.name);
    if (ent.isDirectory()) {
      await copyDir(from, to, baseForRel, copiedOut);
    } else if (ent.isFile()) {
      await fsp.copyFile(from, to);
      copiedOut.push(path.relative(baseForRel, to));
    }
  }
}
}
